// Go emitter (clients/go, module github.com/xantiagoma/xtandard-image/clients/go):
// writes the generated files of the Go client from the spec.
//
//   zz_generated.go                     package xtandard: the catalogue name tables
//                                       (Catalogue.Canonical, Catalogue.Short), the
//                                       constants (formats, containers, streams,
//                                       sources, signing, encryption, URL rules, query
//                                       keys, imaginary) and the error kinds
//   zz_generated_responses.go           package xtandard: the JSON bodies
//                                       (InfoResponse, ErrorResponse, …)
//   processing/, info/, video/          one typed struct per option form, with an
//     zz_generated.go                   enum type per enum argument
//   imgproxy/zz_generated_methods.go    the fluent chains' per-option methods
//   query/zz_generated_methods.go
//
// The output goes through gofmt (on PATH with the Go toolchain), so the
// generator does not have to align struct fields and const blocks itself.

import { allArgs, nameTable, words } from "../lib.ts";
import type { CatalogueKind, Emitter, JSONSchema, Spec, SpecArg, SpecForm, SpecOption } from "../spec.ts";

const dir = "clients/go/";
const module = "github.com/xantiagoma/xtandard-image/clients/go";

const header = (pkg: string, what: string) =>
  [
    "// Code generated by clients/codegen/emitters/go.ts from clients/spec/spec.json. DO NOT EDIT.",
    "// Run `task clients:generate`.",
    "",
    `// ${what}`,
    "",
    `package ${pkg}`,
    "",
  ].join("\n");

/** Words written in upper case (Go initialisms) or with a fixed casing in identifiers. */
const casing: Record<string, string> = {
  id: "ID",
  url: "URL",
  uri: "URI",
  pdf: "PDF",
  rgb: "RGB",
  rgba: "RGBA",
  hdr: "HDR",
  sdr: "SDR",
  dpi: "DPI",
  dpr: "DPR",
  fps: "FPS",
  bps: "BPS",
  crf: "CRF",
  icc: "ICC",
  exif: "EXIF",
  iptc: "IPTC",
  xmp: "XMP",
  css: "CSS",
  mime: "MIME",
  http: "HTTP",
  https: "HTTPS",
  ftp: "FTP",
  sftp: "SFTP",
  json: "JSON",
  md5: "MD5",
  sha1: "SHA1",
  sha256: "SHA256",
  sha512: "SHA512",
  dssim: "DSSIM",
  ml: "ML",
  jpeg: "JPEG",
  jpg: "JPG",
  png: "PNG",
  gif: "GIF",
  avif: "AVIF",
  jxl: "JXL",
  heic: "HEIC",
  tiff: "TIFF",
  bmp: "BMP",
  ico: "ICO",
  svg: "SVG",
  webp: "WebP",
  webm: "WebM",
  mp4: "MP4",
  mp3: "MP3",
  m4a: "M4A",
  wav: "WAV",
  ogg: "OGG",
  flac: "FLAC",
  aac: "AAC",
  pcm: "PCM",
  hevc: "HEVC",
  av1: "AV1",
  vp9: "VP9",
  h264: "H264",
  h265: "H265",
  hls: "HLS",
  dash: "DASH",
  m3u8: "M3U8",
  mpd: "MPD",
  ts: "TS",
  fmp4: "FMP4",
  cmaf: "CMAF",
  mpegts: "MPEGTS",
  s3: "S3",
  gs: "GS",
  abs: "ABS",
  xi: "Xi",
};

/** A Go exported identifier for a name ("min-width" → "MinWidth", "pdf_password" → "PDFPassword"). */
function ident(name: string): string {
  const id = words(name)
    .map((w) => casing[w.toLowerCase()] ?? w[0]!.toUpperCase() + w.slice(1))
    .join("");
  if (id === "") throw new Error(`no identifier for ${JSON.stringify(name)}`);
  return /^[0-9]/.test(id) ? `V${id}` : id;
}

const str = (s: string) => JSON.stringify(s);

/** A Go doc comment: each line of text prefixed with "// ". */
function doc(text: string, indent = ""): string[] {
  return text
    .trim()
    .split("\n")
    .map((l) => (l.trim() === "" ? `${indent}//` : `${indent}// ${l.trimEnd()}`));
}

/** Pipes Go source through gofmt; the emitted files are what gofmt writes. */
function gofmt(path: string, src: string): string {
  let res: ReturnType<typeof Bun.spawnSync>;
  try {
    res = Bun.spawnSync(["gofmt"], { stdin: new TextEncoder().encode(src), stdout: "pipe", stderr: "pipe" });
  } catch (e) {
    throw new Error(`the Go emitter needs gofmt on PATH (the Go toolchain): ${String(e)}`);
  }
  if (res.exitCode !== 0) {
    throw new Error(`gofmt rejected the generated ${path}:\n${res.stderr?.toString()}\n${src}`);
  }
  return res.stdout!.toString();
}

const kindInfo: Record<CatalogueKind, { pkg: string; catalogue: string; iface: string; method: string }> = {
  processing: { pkg: "processing", catalogue: "CatalogueProcessing", iface: "ProcessingOption", method: "ProcessingOption" },
  info: { pkg: "info", catalogue: "CatalogueInfo", iface: "InfoOption", method: "InfoOption" },
  video: { pkg: "video", catalogue: "CatalogueVideo", iface: "VideoOption", method: "VideoOption" },
};

function optionSummary(o: SpecOption): string[] {
  const lines = [`URL names: ${[o.name, ...o.aliases].join(", ")} (short: ${o.short}); arguments ${o.syntax}; default ${o.default}.`];
  const tags: string[] = [];
  if (o.milestone) tags.push(`milestone ${o.milestone}`);
  tags.push(`scope ${o.scope}`);
  if (o.pro) tags.push("imgproxy Pro option (free here)");
  if (o.security) tags.push("security option (needs XI_SECURITY_ALLOW_SECURITY_OPTIONS)");
  if (o.removed) tags.push("removed: accepted and ignored");
  lines.push(`${tags.join("; ")}.`);
  return lines;
}

// ---- package xtandard: tables and constants ---------------------------------

/** One typed string enumeration: `type T string` with a constant per value. */
function enumType(name: string, values: readonly string[], text: string, opts: { doc?: (v: string) => string } = {}): string[] {
  const out = [...doc(text), `type ${name} string`, "", "// Values of " + name + ".", "const ("];
  const seen = new Set<string>();
  for (const v of values) {
    const c = `${name}${ident(v)}`;
    if (seen.has(c)) throw new Error(`duplicate constant ${c}`);
    seen.add(c);
    if (opts.doc) out.push(...doc(opts.doc(v), "\t"));
    out.push(`\t${c} ${name} = ${str(v)}`);
  }
  out.push(")", "");
  return out;
}

function sliceFunc(name: string, type: string, values: readonly (string | number)[], text: string): string[] {
  const items = values.map((v) => (typeof v === "string" ? (type === "string" ? str(v) : `${type}(${str(v)})`) : String(v)));
  return [...doc(text), `func ${name}() []${type} {`, `\treturn []${type}{${items.join(", ")}}`, "}", ""];
}

function emitRoot(spec: Spec): string {
  const out: string[] = [header("xtandard", "Catalogue tables and constants of the client specification.")];
  out.push(`// SpecVersion is the version of clients/spec/spec.json this package was generated from.`);
  out.push(`const SpecVersion = ${spec.spec_version}`, "");

  // Catalogue tables.
  out.push("// canonicalName returns the canonical name of an option name or alias of a catalogue.");
  out.push("func canonicalName(c Catalogue, name string) (string, bool) {");
  out.push("\tswitch c {");
  for (const kind of ["processing", "info", "video"] as const) {
    out.push(`\tcase ${kindInfo[kind].catalogue}:`);
    out.push("\t\tswitch name {");
    const byCanonical = new Map<string, string[]>();
    for (const [n, c] of nameTable(spec.options[kind])) byCanonical.set(c, [...(byCanonical.get(c) ?? []), n]);
    for (const o of spec.options[kind]) {
      out.push(`\t\tcase ${byCanonical.get(o.name)!.map(str).join(", ")}:`);
      out.push(`\t\t\treturn ${str(o.name)}, true`);
    }
    out.push("\t\t}");
  }
  out.push("\t}");
  out.push('\treturn "", false');
  out.push("}", "");
  out.push("// shortName returns the name builders write by default for a canonical option name.");
  out.push("func shortName(c Catalogue, canonical string) string {");
  out.push("\tswitch c {");
  for (const kind of ["processing", "info", "video"] as const) {
    const differ = spec.options[kind].filter((o) => o.short !== o.name);
    out.push(`\tcase ${kindInfo[kind].catalogue}:`);
    out.push("\t\tswitch canonical {");
    for (const o of differ) {
      out.push(`\t\tcase ${str(o.name)}:`);
      out.push(`\t\t\treturn ${str(o.short)}`);
    }
    out.push("\t\t}");
  }
  out.push("\t}");
  out.push("\treturn canonical");
  out.push("}", "");
  out.push("// catalogueNames returns every option name and alias of a catalogue, sorted.");
  out.push("func catalogueNames(c Catalogue) []string {");
  out.push("\tswitch c {");
  for (const kind of ["processing", "info", "video"] as const) {
    out.push(`\tcase ${kindInfo[kind].catalogue}:`);
    out.push(`\t\treturn []string{${nameTable(spec.options[kind]).map(([n]) => str(n)).join(", ")}}`);
  }
  out.push("\t}");
  out.push("\treturn nil");
  out.push("}", "");

  // Media.
  const m = spec.media;
  const s = m.streams;
  out.push(...enumType("ImageFormat", m.image_formats, "ImageFormat is an output format of the processing format option (an extension of a processing URL)."));
  out.push(...sliceFunc("ImageFormats", "ImageFormat", m.image_formats, "ImageFormats returns every ImageFormat."));
  out.push(...enumType("VideoContainer", m.video_containers, "VideoContainer is an output container of /video URLs (their extension)."));
  out.push(...sliceFunc("VideoContainers", "VideoContainer", m.video_containers, "VideoContainers returns every VideoContainer."));
  out.push(...enumType("StreamProtocol", s.protocols.map((p) => p.name), "StreamProtocol is an adaptive streaming protocol: HLS or DASH."));
  out.push("// Manifest returns the protocol's manifest container (the URL extension) and media type; ok is false for an unknown protocol.");
  out.push("func (p StreamProtocol) Manifest() (container VideoContainer, contentType string, ok bool) {");
  out.push("\tswitch p {");
  for (const p of s.protocols) {
    out.push(`\tcase ${str(p.name)}:`);
    out.push(`\t\treturn ${str(p.container)}, ${str(p.content_type)}, true`);
  }
  out.push("\t}");
  out.push('\treturn "", "", false');
  out.push("}", "");
  out.push(
    ...enumType(
      "SegmentFormat",
      s.segment_formats.map((f) => f.name),
      "SegmentFormat is a stream segment container: fmp4 (CMAF, the default) or ts (MPEG-TS, HLS only).",
    ),
  );
  out.push("// Protocols returns the stream protocols a segment format is available for (nil for an unknown format).");
  out.push("func (f SegmentFormat) Protocols() []StreamProtocol {");
  out.push("\tswitch f {");
  for (const f of s.segment_formats) {
    out.push(`\tcase ${str(f.name)}:`);
    out.push(`\t\treturn []StreamProtocol{${f.protocols.map(str).join(", ")}}`);
  }
  out.push("\t}");
  out.push("\treturn nil");
  out.push("}", "");
  out.push("// Stream limits.");
  out.push("const (");
  out.push("\t// DefaultSegmentFormat is the segment format the server uses when a URL names none.");
  out.push(`\tDefaultSegmentFormat SegmentFormat = ${str(s.segment_formats.find((f) => f.default)!.name)}`);
  out.push("\t// MaxRenditions is the most renditions a stream URL may ask for.");
  out.push(`\tMaxRenditions = ${s.max_renditions}`);
  out.push("\t// RenditionMin and RenditionMax bound a rendition (the short side of the frame, in pixels).");
  out.push(`\tRenditionMin = ${s.rendition_min}`);
  out.push(`\tRenditionMax = ${s.rendition_max}`);
  out.push("\t// SegmentDurationMin and SegmentDurationMax bound the segment duration in seconds.");
  out.push(`\tSegmentDurationMin = ${s.segment_duration_min}`);
  out.push(`\tSegmentDurationMax = ${s.segment_duration_max}`);
  out.push(")", "");

  // Sources.
  const src = spec.sources;
  out.push(
    ...enumType("SourceScheme", src.schemes.map((x) => x.scheme), "SourceScheme is a source scheme the server resolves.", {
      doc: (v) => {
        const sc = src.schemes.find((x) => x.scheme === v)!;
        return `Authority: ${sc.authority}; for example ${sc.example}.`;
      },
    }),
  );
  out.push(
    ...enumType(
      "SourceEncoding",
      src.encodings,
      "SourceEncoding is how an imgproxy URL carries its source: base64url (the default), plain (percent-escaped) or encrypted (enc/).",
    ),
  );
  out.push("// XiNamePattern is the pattern of an xi:// source name (XI_SOURCES).");
  out.push(`const XiNamePattern = ${str(src.xi_name_pattern)}`, "");

  // Query dialect.
  const q = spec.query;
  out.push("// QueryMount is the default mount prefix of the query dialect (XI_DIALECTS_QUERY_PREFIX).");
  out.push(`const QueryMount = ${str(q.mount)}`, "");
  out.push("// Native keys of /q/ image URLs (their aliases too); url, o, format, pdp and xi_sig are written by the query builder.");
  out.push("const (");
  for (const k of q.image_keys) {
    for (const n of [k.name, ...k.aliases]) {
      out.push(...doc(`QueryKey${ident(n)} is ${n === k.name ? "" : `an alias of ${k.name}: `}${k.doc}`, "\t"));
      out.push(`\tQueryKey${ident(n)} = ${str(n)}`);
    }
  }
  out.push(")", "");
  out.push("// nativeVideoKey returns the /q/video key of a /video option name (crop is c, flip is fl).");
  out.push("func nativeVideoKey(name string) string {");
  out.push("\tswitch name {");
  for (const [k, v] of Object.entries(q.native_video_keys).sort()) {
    out.push(`\tcase ${str(k)}:`);
    out.push(`\t\treturn ${str(v)}`);
  }
  out.push("\t}");
  out.push("\treturn name");
  out.push("}", "");
  out.push(...enumType("ImaginaryEndpoint", q.imaginary.endpoints, "ImaginaryEndpoint is an imaginary endpoint of /q/<endpoint>."));
  const reservedImaginary = new Set(["url", "sign", "xi_sig"]);
  out.push("// Parameters of imaginary endpoints; url and the signatures are written by the query builder.");
  out.push("const (");
  for (const p of q.imaginary.params) {
    if (reservedImaginary.has(p)) continue;
    out.push(`\tImaginaryParam${ident(p)} = ${str(p)}`);
  }
  out.push(")", "");

  // Signing and encryption.
  const sg = spec.signing;
  const en = spec.encryption;
  const u = spec.url;
  out.push("// Signing constants.");
  out.push("const (");
  out.push("\t// MinSignatureSize and MaxSignatureSize bound a signature size in bytes before encoding (XI_SIGNING_SIZE).");
  out.push(`\tMinSignatureSize = ${sg.min_size}`);
  out.push(`\tMaxSignatureSize = ${sg.max_size}`);
  out.push("\t// DefaultSignatureSize is the full HMAC-SHA256 size.");
  out.push(`\tDefaultSignatureSize = ${sg.default_size}`);
  out.push("\t// DefaultUnsigned is the signature segment of unsigned imgproxy URLs.");
  out.push(`\tDefaultUnsigned = ${str(sg.default_unsigned)}`);
  out.push("\t// XiSigParam is the query parameter of xi_sig signatures.");
  out.push(`\tXiSigParam = ${str(sg.query_param)}`);
  out.push(")", "");
  out.push(...sliceFunc("UnsignedPlaceholders", "string", sg.unsigned_placeholders, "UnsignedPlaceholders returns the signature segments the server accepts on unsigned URLs."));
  out.push("// Encryption constants.");
  out.push("const (");
  out.push("\t// IVSize is the AES-CBC IV size in bytes.");
  out.push(`\tIVSize = ${en.iv_size}`);
  out.push("\t// EncryptedSourcePrefix starts an encrypted source segment.");
  out.push(`\tEncryptedSourcePrefix = ${str(en.source_prefix)}`);
  out.push("\t// MaxPDFPasswordBytes is the longest PDF password, in UTF-8 bytes.");
  out.push(`\tMaxPDFPasswordBytes = ${en.max_pdf_password_bytes}`);
  out.push("\t// PDFPasswordName and PDFPasswordShort are the names of the PDF password option.");
  out.push(`\tPDFPasswordName = ${str(en.pdf_password_names[0]!)}`);
  out.push(`\tPDFPasswordShort = ${str(en.pdf_password_short_name)}`);
  out.push(")", "");
  out.push(...sliceFunc("EncryptionKeySizes", "int", en.key_sizes, "EncryptionKeySizes returns the AES key sizes in bytes."));
  out.push("// URL grammar constants.");
  out.push("const (");
  out.push("\t// DefaultSeparator separates an option's name and arguments (XI_DIALECTS_IMGPROXY_ARGUMENTS_SEPARATOR).");
  out.push(`\tDefaultSeparator = ${str(u.default_separator)}`);
  out.push("\t// PipelineSeparator is the segment between chained pipelines.");
  out.push(`\tPipelineSeparator = ${str(u.pipeline_separator)}`);
  out.push("\t// PlainSafe lists the characters a plain source keeps verbatim besides ASCII letters and digits.");
  out.push(`\tPlainSafe = ${str(u.plain_safe)}`);
  out.push("\t// QuerySafe lists the characters a query key or value keeps verbatim besides ASCII letters and digits.");
  out.push(`\tQuerySafe = ${str(u.query_safe)}`);
  out.push("\t// ExtensionPattern is the pattern of an output extension.");
  out.push(`\tExtensionPattern = ${str(u.extension_pattern)}`);
  out.push(")", "");
  out.push(...sliceFunc("ForbiddenSeparators", "string", u.forbidden_separators, "ForbiddenSeparators returns the separators imgproxy URLs cannot use."));
  out.push(...sliceFunc("ForbiddenQuerySeparators", "string", u.forbidden_query_separators, "ForbiddenQuerySeparators returns the separators the query dialect's o= cannot use."));

  // Error kinds.
  out.push("// ErrorKind is the kind of the server's JSON error envelope. It is an error, so an *HTTPError");
  out.push("// matches its kind with errors.Is (errors.Is(err, xtandard.ErrorKindNotFound)).");
  out.push("type ErrorKind string //nolint:errname // kinds are constant sentinels named like the server's kinds");
  out.push("");
  out.push("// Values of ErrorKind.");
  out.push("const (");
  for (const e of spec.error_kinds) {
    out.push(`\t// ErrorKind${ident(e.kind)} is HTTP ${e.status}: ${e.message}.`);
    out.push(`\tErrorKind${ident(e.kind)} ErrorKind = ${str(e.kind)}`);
  }
  out.push(")", "");
  out.push('// Error implements error: the kind itself ("not_found").');
  out.push("func (k ErrorKind) Error() string { return string(k) }");
  out.push("");
  out.push("// ErrorKindFor returns the error kind of a plain-text error response: the kind whose status and");
  out.push("// public message match (the server writes the message alone when Accept does not list JSON).");
  out.push("func ErrorKindFor(status int, message string) (ErrorKind, bool) {");
  out.push("\tswitch {");
  for (const e of spec.error_kinds) {
    if (e.kind === "unknown") continue;
    out.push(`\tcase status == ${e.status} && message == ${str(e.message)}:`);
    out.push(`\t\treturn ErrorKind${ident(e.kind)}, true`);
  }
  out.push("\t}");
  out.push('\treturn ErrorKindUnknown, false');
  out.push("}", "");
  out.push("// Status returns the HTTP status the server answers an error kind with (0 for an unknown kind).");
  out.push("func (k ErrorKind) Status() int {");
  out.push("\tswitch k {");
  for (const e of spec.error_kinds) {
    out.push(`\tcase ${str(e.kind)}:`);
    out.push(`\t\treturn ${e.status}`);
  }
  out.push("\t}");
  out.push("\treturn 0");
  out.push("}", "");
  return out.join("\n");
}

// ---- package xtandard: responses -----------------------------------------------

function schemaType(s: JSONSchema, optional: boolean): string {
  if (s.$ref) {
    const t = s.$ref.replace("#/components/schemas/", "");
    return `*${t}`;
  }
  const types = (s.type === undefined ? [] : Array.isArray(s.type) ? s.type : [s.type]).filter((t) => t !== "null");
  if (s.enum) {
    const t = s.enum.every((v) => typeof v === "string") && s.enum.includes("not_found") ? "ErrorKind" : "string";
    return optional ? `*${t}` : t;
  }
  const t = types[0];
  switch (t) {
    case "string":
      return optional ? "*string" : "string";
    case "integer":
      return optional ? "*int64" : "int64";
    case "number":
      return optional ? "*float64" : "float64";
    case "boolean":
      return optional ? "*bool" : "bool";
    case "array":
      return `[]${s.items ? schemaType(s.items, false).replace(/^\*/, "") : "any"}`;
    case "object":
      if (s.properties) throw new Error("inline object schemas are not supported");
      return `map[string]${typeof s.additionalProperties === "object" ? schemaType(s.additionalProperties, false) : "any"}`;
    default:
      return "any";
  }
}

function emitResponses(spec: Spec): string {
  const out: string[] = [header("xtandard", "JSON response bodies of the server (the OpenAPI components).")];
  for (const name of Object.keys(spec.response_schemas).sort()) {
    const s = spec.response_schemas[name]!;
    out.push(...doc(`${name} is the ${name} schema of the server's OpenAPI document.${s.description ? `\n\n${s.description}` : ""}`));
    out.push(`type ${name} struct {`);
    const req = new Set(s.required ?? []);
    for (const [p, ps] of Object.entries(s.properties ?? {}).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
      const optional = !req.has(p);
      if (ps.description) out.push(...doc(ps.description, "\t"));
      const omit = optional ? ",omitempty" : "";
      out.push(`\t${ident(p)} ${schemaType(ps, optional)} \`json:"${p}${omit}"\``);
    }
    out.push("}", "");
  }
  return out.join("\n");
}

// ---- processing/, info/, video/: typed option values ----------------------------

interface FieldPlan {
  /** Go field name, or undefined for a fixed discriminator. */
  field?: string;
  /** Go type of the field. */
  type?: string;
  /** Expression of the argument (o.Field, core.Deref(o.Field) or a constant). */
  expr: string;
  doc: string;
}

function argDoc(a: SpecArg): string {
  const parts: string[] = [];
  if (a.doc) parts.push(a.doc.trim().replace(/\.$/, ""));
  if (a.enum && a.enum.length > 1) parts.push(`one of ${a.enum.join(", ")}`);
  if (a.min !== undefined || a.max !== undefined) {
    parts.push(`range ${a.min ?? "-∞"}${a.exclusive_min ? " (exclusive)" : ""} to ${a.max ?? "∞"}`);
  }
  if (a.multiple_of) parts.push(`a multiple of ${a.multiple_of}`);
  if (a.pattern) parts.push(`pattern ${a.pattern}`);
  return parts.join("; ");
}

function plural(name: string): string {
  return /(s|x|ch|sh)$/.test(name) ? `${name}es` : `${name}s`;
}

function emitTyped(spec: Spec, kind: CatalogueKind): string {
  const k = kindInfo[kind];
  const out: string[] = [header(k.pkg, `Typed ${kind} options: one struct per option form, implementing xtandard.${k.iface}.`)];
  out.push("import (");
  out.push(`\txtandard ${str(module)}`);
  out.push(`\t${str(`${module}/internal/core`)}`);
  out.push(")", "");
  const used = new Set<string>();
  const claim = (id: string, what: string) => {
    if (used.has(id)) throw new Error(`${kind}: the Go identifier ${id} (${what}) is used twice`);
    used.add(id);
  };
  const enums: string[] = [];
  const optionTypes: string[] = [];
  const enumOf = new Map<string, string>(); // option/arg -> type name

  const enumName = (o: SpecOption, a: SpecArg): string => {
    const key = `${o.name}/${a.name}`;
    const have = enumOf.get(key);
    if (have) return have;
    const base = ident(o.name);
    const an = ident(a.name);
    const name = an === base ? `${base}Value` : `${base}${an}`;
    claim(name, `enum ${key}`);
    enumOf.set(key, name);
    enums.push(...doc(`${name} is argument ${a.name} of ${kind} option ${o.name}: ${a.doc ?? a.name}.`));
    enums.push(`type ${name} string`, "", `// Values of ${name}.`, "const (");
    for (const v of a.enum!) {
      const c = `${name}${ident(v)}`;
      claim(c, `enum value ${key}=${v}`);
      enums.push(`\t${c} ${name} = ${str(v)}`);
    }
    enums.push(")", "");
    return name;
  };

  const valueType = (o: SpecOption, a: SpecArg, optional: boolean): { type: string; ptr: boolean } => {
    switch (a.type) {
      case "integer":
        return { type: optional ? "*int" : "int", ptr: optional };
      case "number":
        return { type: optional ? "*float64" : "float64", ptr: optional };
      case "boolean":
        return { type: optional ? "*bool" : "bool", ptr: optional };
      case "enum":
        return { type: enumName(o, a), ptr: false };
      default:
        // string, color, base64, direction: "" is an empty argument.
        return { type: "string", ptr: false };
    }
  };

  for (const o of spec.options[kind]) {
    const base = ident(o.name);
    o.forms.forEach((f: SpecForm, fi: number) => {
      // Name: the option, then the discriminator value or the argument names.
      let name = base;
      if (fi > 0) {
        const disc = f.args.find((a) => a.type === "enum" && a.enum?.length === 1);
        name = disc ? `${base}${ident(disc.enum![0]!)}` : `${base}${ident(f.args.map((a) => a.name).join("_")) || `Form${fi}`}`;
      }
      claim(name, `${kind} option ${o.name} form ${fi}`);
      optionTypes.push(name);
      const min = Math.max(f.min_items, 1);
      const fields: FieldPlan[] = [];
      f.args.forEach((a, i) => {
        if (a.type === "enum" && a.enum?.length === 1) {
          fields.push({ expr: str(a.enum[0]!), doc: "" });
          return;
        }
        const optional = a.nullable || i >= min;
        const fname = ident(a.name);
        const { type, ptr } = valueType(o, a, optional);
        fields.push({ field: fname, type, expr: ptr ? `core.Deref(o.${fname})` : `o.${fname}`, doc: argDoc(a) });
      });
      const rest = f.rest ?? [];
      let restField: string | undefined;
      let restItem: string | undefined;
      const restExprs: string[] = [];
      if (rest.length === 1) {
        restField = ident(plural(rest[0]!.name));
        const { type } = valueType(o, rest[0]!, false);
        restItem = type;
      } else if (rest.length > 1) {
        restField = "Items";
        restItem = `${name}Item`;
        claim(restItem, `${kind} option ${o.name} rest item`);
        for (const a of rest) restExprs.push(`it.${ident(a.name)}`);
      }
      const names = new Set<string>();
      for (const fp of fields) {
        if (fp.field === undefined) continue;
        if (names.has(fp.field)) throw new Error(`${kind} ${o.name}: field ${fp.field} twice`);
        names.add(fp.field);
      }
      if (restField && names.has(restField)) throw new Error(`${kind} ${o.name}: field ${restField} twice`);

      const formText =
        o.forms.length > 1
          ? `\n\nForm ${fi + 1} of ${o.forms.length}: ${f.args.map((a) => (a.type === "enum" && a.enum?.length === 1 ? a.enum[0] : a.name)).join(":")}${rest.length ? `[:${rest.map((a) => a.name).join(":")}]…` : ""}.`
          : "";
      out.push(...doc(`${name} is the ${kind} option ${o.name}: ${o.doc}${formText}\n\n${optionSummary(o).join("\n")}`));
      const empty = !restField && fields.every((fp) => fp.field === undefined);
      out.push(empty ? `type ${name} struct{}` : `type ${name} struct {`);
      for (const fp of fields) {
        if (fp.field === undefined) continue;
        if (fp.doc) out.push(...doc(`${fp.field}: ${fp.doc}.`, "\t"));
        out.push(`\t${fp.field} ${fp.type}`);
      }
      if (restField) {
        const restDoc =
          rest.length === 1
            ? `${restField}: the repeated ${rest[0]!.name} arguments${rest[0]!.doc ? ` (${argDoc(rest[0]!)})` : ""}.`
            : `${restField}: the repeated ${rest.map((a) => a.name).join(":")} groups.`;
        out.push(...doc(restDoc, "\t"));
        out.push(`\t${restField} []${restItem}`);
      }
      if (!empty) out.push("}");
      out.push("");
      if (rest.length > 1) {
        out.push(`// ${restItem} is one repeated group of ${name}.`);
        out.push(`type ${restItem} struct {`);
        for (const a of rest) {
          const { type } = valueType(o, a, false);
          if (a.doc) out.push(...doc(`${ident(a.name)}: ${argDoc(a)}.`, "\t"));
          out.push(`\t${ident(a.name)} ${type}`);
        }
        out.push("}", "");
      }
      out.push(`// ${k.method} returns the option as xtandard.Option ${o.name} (unset trailing arguments are left out).`);
      out.push(`func (o ${name}) ${k.method}() xtandard.Option {`);
      out.push(`\targs := []xtandard.Arg{${fields.map((fp) => fp.expr).join(", ")}}`);
      if (restField) {
        out.push(`\tif len(o.${restField}) > 0 {`);
        if (rest.length === 1) {
          out.push(`\t\tfor _, v := range o.${restField} {`);
          out.push("\t\t\targs = append(args, v)");
          out.push("\t\t}");
        } else {
          out.push(`\t\tfor _, it := range o.${restField} {`);
          out.push(`\t\t\targs = append(args, ${restExprs.join(", ")})`);
          out.push("\t\t}");
        }
        out.push(`\t\treturn xtandard.Option{Name: ${str(o.name)}, Args: args}`);
        out.push("\t}");
      }
      out.push(`\treturn xtandard.Option{Name: ${str(o.name)}, Args: core.Trim(args, ${min})}`);
      out.push("}", "");
    });
  }
  out.push(...enums);
  out.push("// Compile-time checks: every option type implements the catalogue's interface.");
  out.push("var (");
  for (const id of optionTypes) out.push(`\t_ xtandard.${k.iface} = ${id}{}`);
  out.push(")", "");
  return out.join("\n");
}

// ---- imgproxy/ and query/: fluent per-option methods ----------------------------

/** Control methods of the chains; a per-option method must not take one of these names. */
export const reservedMethods = new Set(["Option", "With", "Pipeline", "Extension", "Encoding", "WithPDFPassword", "Build", "Param", "Err"]);

function methods(spec: Spec, kind: CatalogueKind, chain: string): string[] {
  const out: string[] = [];
  const used = new Map<string, string>();
  for (const o of spec.options[kind]) {
    const argNames = allArgs(o).map((a) => a.name);
    for (const n of [o.name, ...o.aliases]) {
      const id = ident(n);
      if (reservedMethods.has(id)) throw new Error(`${kind} option ${n} collides with the chain method ${id}`);
      const prev = used.get(id);
      if (prev !== undefined) throw new Error(`${kind} option names ${prev} and ${n} are both the Go method ${id}`);
      used.set(id, n);
      const what = n === o.name ? `${kind} option ${o.name}` : `${kind} option ${o.name} under its alias ${n}`;
      out.push(...doc(`${id} appends the ${what}: ${o.doc}\n\nArguments: ${o.syntax}${argNames.length ? ` (${[...new Set(argNames)].join(", ")})` : ""}. With GivenNames the option is written as ${str(n)}.`));
      out.push(`func (c *${chain}) ${id}(args ...xtandard.Arg) *${chain} {`);
      out.push(`\treturn c.Option(${str(n)}, args...)`);
      out.push("}", "");
    }
  }
  return out;
}

function emitMethods(spec: Spec, pkg: string, chains: [CatalogueKind, string][]): string {
  const out: string[] = [header(pkg, "Per-option methods of the fluent URL chains: one per option name and alias.")];
  out.push(`import xtandard ${str(module)}`, "");
  for (const [kind, chain] of chains) {
    out.push(`// ---- ${chain}: ${kind} options ----`, "");
    out.push(...methods(spec, kind, chain));
  }
  return out.join("\n");
}

export const emitter: Emitter = {
  language: "go",
  emit(spec) {
    const files: Record<string, string> = {
      [`${dir}zz_generated.go`]: emitRoot(spec),
      [`${dir}zz_generated_responses.go`]: emitResponses(spec),
      [`${dir}processing/zz_generated.go`]: emitTyped(spec, "processing"),
      [`${dir}info/zz_generated.go`]: emitTyped(spec, "info"),
      [`${dir}video/zz_generated.go`]: emitTyped(spec, "video"),
      [`${dir}imgproxy/zz_generated_methods.go`]: emitMethods(spec, "imgproxy", [
        ["processing", "ImageChain"],
        ["info", "InfoChain"],
        ["video", "VideoChain"],
      ]),
      [`${dir}query/zz_generated_methods.go`]: emitMethods(spec, "query", [
        ["processing", "ImageChain"],
        ["video", "VideoChain"],
      ]),
    };
    for (const [path, src] of Object.entries(files)) files[path] = gofmt(path, src);
    return files;
  },
};
